 const battery=new T.Group();battery.position.set(0,-.025,.16);internal.add(battery);part(battery,new T.BoxGeometry(.17,.008,.20),dark,0,-.045,0,'battery tray');for(let i=0;i<8;i++){cylinder(battery,.017,.16,material(0xb4b883),(i%4-1.5)*.039,(Math.floor(i/4)-.5)*.037,0,'lithium-ion cells')}line(battery,[[.06,.04,-.08],[.08,.07,-.12],[.08,.06,-.16]],orange,.004);
 const batteryCover=part(body,new T.BoxGeometry(.018,.075,.22),silver,-.136,-.06,.17,'battery bay cover');const batteryCoverTrim=part(body,new T.BoxGeometry(.022,.085,.23),dark,-.13,-.06,.17);
 const chemical=new T.Group();chemical.position.set(.015,-.20,.14);body.add(chemical);for(const x of [-.05,.05]){const tank=part(chemical,new T.CapsuleGeometry(.047,.12,8,24),green,x,0,0,'chemical tank');tank.rotation.x=Math.PI/2;cylinder(chemical,.014,.03,silver,x,0,-.115,'tank valve');for(const z of [-.045,.045]){const band=part(chemical,new T.TorusGeometry(.049,.004,8,24),dark,x,0,z)}}line(chemical,[[-.05,0,-.13],[-.1,-.015,-.15],[-.1,-.025,-.22]],orange,.004);
 const hydro=new T.Group();hydro.position.set(0,-.20,-.12);body.add(hydro);cylinder(hydro,.045,.12,blue,0,0,0,'hydro pump');cylinder(hydro,.028,.035,silver,0,0,-.077,'pump outlet');line(body,[[.04,-.2,-.10],[.085,-.22,-.16],[.085,-.22,-.28]],blue,.009);cylinder(hydro,.009,.14,silver,.085,-.02,-.11,'back-flush nozzle');
 const vacuum=new T.Group();vacuum.position.set(.045,-.235,-.35);body.add(vacuum);cylinder(vacuum,.029,.30,silver,0,0,0,'vacuum suction tube');for(let i=0;i<10;i++)part(vacuum,new T.TorusGeometry(.030,.0035,8,24),dark,0,0,(i-4.5)*.026);const intake=part(vacuum,new T.ConeGeometry(.04,.055,24,1,true),silver,0,0,-.17);intake.rotation.x=-Math.PI/2;const hole=part(vacuum,new T.CircleGeometry(.029,24),black,0,0,-.197);hole.rotation.y=Math.PI;
